function mdl = build_islanding_model()
%BUILD_ISLANDING_MODEL Create gridsetu_islanding.slx (Simulink, R2020b or newer).
%   The model is generated by this script so it can be rebuilt and reviewed as text:
%
%     Digital Clock --t-->  +----------------------------+ --xn--> Unit Delay (state) --x--+
%     Variant (0/1/2) ----> |  GridSetu critical bus     |                                 |
%            +--- x ------> |  (MATLAB Function:         | --y----> To Workspace (y_isl)   |
%            |              |   islanding_step.m)        | --f, V, P, I--> four scopes     |
%            |              +----------------------------+                                 |
%            +-------------------------------------------------------------------------- +
%
%   The block calls islanding_step.m, the same function ISLANDING_REFERENCE runs as a plain
%   loop, so RUN_ISLANDING can check that the Simulink model reproduces it exactly.

here = fileparts(mfilename('fullpath'));
addpath(here);
p = islanding_params();
mdl = 'gridsetu_islanding';
if bdIsLoaded(mdl), close_system(mdl, 0); end
f = fullfile(here, [mdl '.slx']);
if exist(f, 'file'), delete(f); end
new_system(mdl);
set_param(mdl, 'SolverType', 'Fixed-step', 'Solver', 'FixedStepDiscrete', ...
    'FixedStep', num2str(p.dt), 'StopTime', num2str(p.t_end), 'ReturnWorkspaceOutputs', 'on');
set_param(mdl, 'Description', ['GridSetu pilot feeder F07: the critical bus (clinic, school, ' ...
    'street lights, water pump) islands on the community battery when the feeder trips, ' ...
    'rides a pump start, and resynchronises when the grid returns. Average-value (RMS) model. ' ...
    'SIMULATION: assumed inverter settings, not a vendor model.']);

B = @(name) [mdl '/' name];
fn   = 'GridSetu critical bus';
mem  = 'State memory';
clk  = 'Clock';
var  = 'Variant (0 baseline, 1 GridSetu following, 2 GridSetu grid-forming)';
logb = 'Log to workspace';

add_block('simulink/Sources/Digital Clock', B(clk), 'SampleTime', num2str(p.dt), ...
    'Position', [40 60 100 90]);
add_block('simulink/Sources/Constant', B(var), 'Value', '2', 'SampleTime', num2str(p.dt), ...
    'Position', [40 130 100 160]);
add_block('simulink/User-Defined Functions/MATLAB Function', B(fn), ...
    'Position', [260 40 460 260]);
add_block('simulink/Discrete/Unit Delay', B(mem), 'SampleTime', num2str(p.dt), ...
    'InitialCondition', mat2str(islanding_x0(p)), 'Position', [330 320 390 360], ...
    'Orientation', 'left');
add_block('simulink/Sinks/To Workspace', B(logb), 'VariableName', 'y_isl', ...
    'SaveFormat', 'Array', 'Decimation', num2str(p.log_every), 'SampleTime', num2str(p.dt), ...
    'MaxDataPoints', 'inf', 'Position', [560 40 660 70]);

code = sprintf([ ...
    'function [xn, y, f_hz, v_pu, p_inv_kw, i_bat_a] = critical_bus(x, t, variant)\n' ...
    '%% One fixed step of the critical-bus islanding model (see islanding_step.m).\n' ...
    'p = islanding_params();\n' ...
    '[xn, y] = islanding_step(x, t, variant, p);\n' ...
    'f_hz = y(2); v_pu = y(3); p_inv_kw = y(4); i_bat_a = y(7);\n' ...
    'end\n']);
set_function_code(B(fn), code);

scopes = {'Frequency (Hz)', 'Critical-bus voltage (pu)', 'Inverter power (kW)', 'Battery current (A)'};
for k = 1:numel(scopes)
    add_block('simulink/Sinks/Scope', B(scopes{k}), ...
        'Position', [560 70 + 55*k 600 100 + 55*k]);
end

add_line(mdl, [clk '/1'], [fn '/2'], 'autorouting', 'on');
add_line(mdl, [var '/1'], [fn '/3'], 'autorouting', 'on');
add_line(mdl, [mem '/1'], [fn '/1'], 'autorouting', 'on');
add_line(mdl, [fn '/1'], [mem '/1'], 'autorouting', 'on');
add_line(mdl, [fn '/2'], [logb '/1'], 'autorouting', 'on');
for k = 1:numel(scopes)
    add_line(mdl, sprintf('%s/%d', fn, k + 2), [scopes{k} '/1'], 'autorouting', 'on');
end

save_system(mdl, f);
fprintf('Built %s\n', f);
end

function set_function_code(blk, code)
% R2020b and newer: MATLABFunctionConfiguration; older releases: the Stateflow API.
try
    cfg = get_param(blk, 'MATLABFunctionConfiguration');
    cfg.FunctionScript = code;
catch
    rt = sfroot;
    ch = rt.find('-isa', 'Stateflow.EMChart', 'Path', blk);
    ch.Script = code;
end
end
